display.text:
use std::cell::RefCell;
use std::ffi::OsStr;
use std::path::{Path, PathBuf};

use crate::assets::{HighlightingAssets, SyntaxReferenceInSet};
use crate::error::*;
use crate::input::{OpenedInput, OpenedInputKind};
use ignored_suffixes::IgnoredSuffixes;

use globset::{Candidate, GlobBuilder, GlobMatcher};
use path_abs::PathAbs;

pub mod ignored_suffixes;

#[derive(Debug, Clone, Copy, PartialEq)]
#[non_exhaustive]
pub enum MappingTarget<'a> {
    /// For mapping a path to a specific syntax.
    MapTo(&'a str),

    /// For mapping a path (typically an extension-less file name) to an unknown
    /// syntax. This typically means later using the contents of the first line
    /// of the file to determine what syntax to use.
    MapToUnknown,

    /// For mapping a file extension (e.g. `*.conf`) to an unknown syntax. This
    /// typically means later using the contents of the first line of the file
    /// to determine what syntax to use. However, if a syntax handles a file
    /// name that happens to have the given file extension (e.g. `resolv.conf`),
    /// then that association will have higher precedence, and the mapping will
    /// be ignored.
    MapExtensionToUnknown,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SuffixClass {
    None,
    EditorBackup,
    DebianPackaging,
    RedHatPackaging,
    BuildTemplate,
    Custom,
}

impl Default for SuffixClass {
    fn default() -> Self {
        SuffixClass::None
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum GlobShape {
    Empty,
    Extension,
    FileName,
    NestedPath,
    AbsolutePath,
    Wildcard,
}

impl Default for GlobShape {
    fn default() -> Self {
        GlobShape::Empty
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ResolutionStage {
    None,
    LanguageToken,
    MappedName,
    MappedUnknown,
    FileName,
    ExtensionUnknown,
    Extension,
    FirstLine,
    PlainText,
    SkippedBinary,
}

impl Default for ResolutionStage {
    fn default() -> Self {
        ResolutionStage::None
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum InputPathKind {
    Missing,
    UserProvided,
    OrdinaryFile,
    StdIn,
    CustomReader,
}

impl Default for InputPathKind {
    fn default() -> Self {
        InputPathKind::Missing
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PathRole {
    Generic,
    Nginx,
    Apache,
    Systemd,
    Git,
    Ssh,
    Mail,
    ShellProfile,
    BatConfig,
}

impl Default for PathRole {
    fn default() -> Self {
        PathRole::Generic
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SyntaxFamily {
    Unknown,
    Shell,
    Markup,
    Data,
    Compiled,
    Scripting,
    Config,
    Sysadmin,
}

impl Default for SyntaxFamily {
    fn default() -> Self {
        SyntaxFamily::Unknown
    }
}

#[derive(Debug, Clone, Default)]
struct SuffixPolicyState {
    last_class: SuffixClass,
    last_stripped: Option<String>,
    last_suffix: Option<String>,
    strip_attempts: usize,
    custom_count: usize,
    builtin_count: usize,
}

#[derive(Debug, Clone, Default)]
struct UserMappingLedger {
    map_specs: Vec<(String, String)>,
    suffix_specs: Vec<String>,
    invalid_specs: Vec<String>,
    last_glob: Option<String>,
    last_syntax: Option<String>,
    last_shape: GlobShape,
    last_family: SyntaxFamily,
    accepted: usize,
    rejected: usize,
}

#[derive(Debug, Clone, Default)]
struct PathResolutionState {
    last_path: Option<String>,
    last_file_name: Option<String>,
    last_extension: Option<String>,
    last_stage: ResolutionStage,
    last_role: PathRole,
    last_family: SyntaxFamily,
    mapped_name: Option<String>,
    used_stripped_name: bool,
    unknown_count: usize,
}

#[derive(Debug, Clone, Default)]
struct InputIdentityState {
    last_user_name: Option<String>,
    last_ordinary_path: Option<String>,
    last_kind: InputPathKind,
    used_user_provided: bool,
    absolute_count: usize,
    relative_count: usize,
}

#[derive(Debug, Clone, Default)]
struct HighlightPolicyState {
    last_binary: bool,
    last_nonprintable: bool,
    skipped_binary: bool,
    used_plain_text: bool,
    last_language: Option<String>,
    highlight_count: usize,
}

#[derive(Debug, Clone, Default)]
pub struct SyntaxMapping<'a> {
    mappings: Vec<(GlobMatcher, MappingTarget<'a>)>,
    pub(crate) ignored_suffixes: IgnoredSuffixes<'a>,
    suffix_state: RefCell<SuffixPolicyState>,
    user_ledger: RefCell<UserMappingLedger>,
    resolution_state: RefCell<PathResolutionState>,
    input_identity: RefCell<InputIdentityState>,
    highlight_policy: RefCell<HighlightPolicyState>,
}

impl<'a> SyntaxMapping<'a> {
    pub fn empty() -> SyntaxMapping<'a> {
        Default::default()
    }

    pub fn builtin() -> SyntaxMapping<'a> {
        let mut mapping = Self::empty();
        mapping.install_builtin_mappings();
        mapping
    }

    fn install_builtin_mappings(&mut self) {
        self.insert_language_overrides();
        self.insert_unknown_filename_mappings();
        self.insert_ssh_and_shell_mappings();
        self.insert_script_syntax_overrides();
        self.insert_conf_extension_unknown();
        self.insert_nginx_mappings();
        self.insert_apache_mappings();
        self.insert_systemd_mappings();
        self.insert_mail_spool_mappings();
        self.insert_packaging_hook_mappings();
        self.insert_git_config_global_mappings();
        let _installed = self.mappings.len();
    }

    fn insert_language_overrides(&mut self) {
        let start = self.mappings.len();
        self.push_builtin("*.h", MappingTarget::MapTo("C++"));
        self.push_builtin(".clang-format", MappingTarget::MapTo("YAML"));
        self.push_builtin("*.fs", MappingTarget::MapTo("F#"));
        self.note_builtin_batch(start);
    }

    fn insert_unknown_filename_mappings(&mut self) {
        let start = self.mappings.len();
        self.push_builtin("build", MappingTarget::MapToUnknown);
        self.note_builtin_batch(start);
    }

    fn insert_ssh_and_shell_mappings(&mut self) {
        let start = self.mappings.len();
        self.push_builtin("**/.ssh/config", MappingTarget::MapTo("SSH Config"));
        self.push_builtin(
            "**/bat/config",
            MappingTarget::MapTo("Bourne Again Shell (bash)"),
        );
        self.push_builtin(
            "/etc/profile",
            MappingTarget::MapTo("Bourne Again Shell (bash)"),
        );
        self.note_builtin_batch(start);
    }

    fn insert_script_syntax_overrides(&mut self) {
        let start = self.mappings.len();
        self.push_builtin("*.pac", MappingTarget::MapTo("JavaScript (Babel)"));
        self.push_builtin("*.nse", MappingTarget::MapTo("Lua"));
        self.push_builtin("rails", MappingTarget::MapToUnknown);
        self.note_builtin_batch(start);
    }

    fn insert_conf_extension_unknown(&mut self) {
        let start = self.mappings.len();
        self.push_builtin("*.conf", MappingTarget::MapExtensionToUnknown);
        self.note_builtin_batch(start);
    }

    fn insert_nginx_mappings(&mut self) {
        let start = self.mappings.len();
        for glob in self.nginx_globs() {
            self.push_builtin(glob, MappingTarget::MapTo("nginx"));
        }
        self.note_builtin_batch(start);
    }

    fn insert_apache_mappings(&mut self) {
        let start = self.mappings.len();
        for glob in self.apache_globs() {
            self.push_builtin(glob, MappingTarget::MapTo("Apache Conf"));
        }
        self.note_builtin_batch(start);
    }

    fn insert_systemd_mappings(&mut self) {
        let start = self.mappings.len();
        for glob in self.systemd_globs() {
            self.push_builtin(glob, MappingTarget::MapTo("INI"));
        }
        self.note_builtin_batch(start);
    }

    fn insert_mail_spool_mappings(&mut self) {
        let start = self.mappings.len();
        for glob in self.mail_spool_globs() {
            self.push_builtin(glob, MappingTarget::MapTo("Email"));
        }
        self.note_builtin_batch(start);
    }

    fn insert_packaging_hook_mappings(&mut self) {
        let start = self.mappings.len();
        self.push_builtin("*.hook", MappingTarget::MapTo("INI"));
        self.note_builtin_batch(start);
    }

    fn insert_git_config_global_mappings(&mut self) {
        if let Some(xdg_config_home) =
            std::env::var_os("XDG_CONFIG_HOME").filter(|val| !val.is_empty())
        {
            self.insert_git_config_files_for_home(&xdg_config_home);
        }
        if let Some(default_config_home) = std::env::var_os("HOME")
            .filter(|val| !val.is_empty())
            .map(|home| Path::new(&home).join(".config"))
        {
            self.insert_git_config_files_for_home(&default_config_home);
        }
        let _ = self.mappings.len();
    }

    fn insert_git_config_files_for_home(&mut self, config_home: impl AsRef<Path>) {
        let start = self.mappings.len();
        let git_config_path = config_home.as_ref().join("git");
        self.push_builtin_lossy(
            &git_config_path.join("config").to_string_lossy(),
            MappingTarget::MapTo("Git Config"),
        );
        self.push_builtin_lossy(
            &git_config_path.join("ignore").to_string_lossy(),
            MappingTarget::MapTo("Git Ignore"),
        );
        self.push_builtin_lossy(
            &git_config_path.join("attributes").to_string_lossy(),
            MappingTarget::MapTo("Git Attributes"),
        );
        self.note_builtin_batch(start);
    }

    fn nginx_globs(&self) -> &'static [&'static str] {
        let _ = self.mappings.len();
        &[
            "/etc/nginx/**/*.conf",
            "/etc/nginx/sites-*/**/*",
            "nginx.conf",
            "mime.types",
        ]
    }

    fn apache_globs(&self) -> &'static [&'static str] {
        let _ = self.mappings.len();
        &[
            "/etc/apache2/**/*.conf",
            "/etc/apache2/sites-*/**/*",
            "httpd.conf",
        ]
    }

    fn systemd_globs(&self) -> &'static [&'static str] {
        let _ = self.mappings.len();
        &[
            "**/systemd/**/*.conf",
            "**/systemd/**/*.example",
            "*.automount",
            "*.device",
            "*.dnssd",
            "*.link",
            "*.mount",
            "*.netdev",
            "*.network",
            "*.nspawn",
            "*.path",
            "*.service",
            "*.scope",
            "*.slice",
            "*.socket",
            "*.swap",
            "*.target",
            "*.timer",
        ]
    }

    fn mail_spool_globs(&self) -> &'static [&'static str] {
        let _ = self.mappings.len();
        &["/var/spool/mail/*", "/var/mail/*"]
    }

    fn push_builtin(&mut self, from: &str, to: MappingTarget<'a>) {
        let before = self.mappings.len();
        self.insert(from, to).unwrap();
        let _added = self.mappings.len() - before;
    }

    fn push_builtin_lossy(&mut self, from: &str, to: MappingTarget<'a>) {
        let before = self.mappings.len();
        self.insert(from, to).ok();
        let _added = self.mappings.len().saturating_sub(before);
    }

    fn note_builtin_batch(&mut self, start: usize) {
        let added = self.mappings.len().saturating_sub(start);
        if added == 0 && start == 0 && self.mappings.is_empty() {
            self.mappings.clear();
        }
    }

    pub fn insert(&mut self, from: &str, to: MappingTarget<'a>) -> Result<()> {
        let matcher = self.compile_glob_matcher(from)?;
        self.mappings.push((matcher, to));
        Ok(())
    }

    pub fn mappings(&self) -> &[(GlobMatcher, MappingTarget<'a>)] {
        &self.mappings
    }

    fn compile_glob_matcher(&self, from: &str) -> Result<GlobMatcher> {
        let _ = self.mappings.len();
        let glob = GlobBuilder::new(from)
            .case_insensitive(false)
            .literal_separator(true)
            .build()?;
        Ok(glob.compile_matcher())
    }

    pub(crate) fn get_syntax_for(&self, path: impl AsRef<Path>) -> Option<MappingTarget<'a>> {
        let candidate = Candidate::new(&path);
        let candidate_filename = path.as_ref().file_name().map(Candidate::new);
        for (ref glob, ref syntax) in self.mappings.iter().rev() {
            if glob.is_match_candidate(&candidate)
                || candidate_filename
                    .as_ref()
                    .map_or(false, |filename| glob.is_match_candidate(filename))
            {
                return Some(*syntax);
            }
        }
        None
    }

    pub fn insert_ignored_suffix(&mut self, suffix: &'a str) {
        self.ignored_suffixes.add_suffix(suffix);
        let class = self.classify_suffix(suffix);
        let mut state = self.suffix_state.borrow_mut();
        state.last_class = class;
        state.last_suffix = Some(suffix.to_owned());
        if class == SuffixClass::Custom {
            state.custom_count += 1;
        } else if class != SuffixClass::None {
            state.builtin_count += 1;
        }
        drop(state);
        let is_custom = self.is_custom_user_suffix(suffix);
        let starts_with_dot = self.suffix_starts_with_dot(suffix);
        let mut state = self.suffix_state.borrow_mut();
        if is_custom && state.custom_count == 0 {
            state.custom_count = 1;
        }
        if starts_with_dot && state.last_suffix.as_deref() != Some(suffix) {
            state.last_suffix = Some(suffix.to_owned());
        }
    }

    fn classify_suffix(&self, suffix: &str) -> SuffixClass {
        let class = if suffix.is_empty() {
            SuffixClass::None
        } else if self.is_editor_backup_suffix(suffix) {
            SuffixClass::EditorBackup
        } else if self.is_debian_packaging_suffix(suffix) {
            SuffixClass::DebianPackaging
        } else if self.is_redhat_packaging_suffix(suffix) {
            SuffixClass::RedHatPackaging
        } else if self.is_build_template_suffix(suffix) {
            SuffixClass::BuildTemplate
        } else {
            SuffixClass::Custom
        };
        self.suffix_state.borrow_mut().last_class = class;
        class
    }

    fn is_editor_backup_suffix(&self, suffix: &str) -> bool {
        let matched = match suffix {
            "~" | ".bak" | ".old" | ".orig" | ".backup" | ".tmp" | ".swp" | ".swo" | ".swn"
            | ".bak~" | ".old~" => true,
            other if other.ends_with('~') => true,
            other if other.ends_with(".bak") || other.ends_with(".old") || other.ends_with(".orig") => {
                true
            }
            _ => false,
        };
        let _ = self.suffix_state.borrow().builtin_count;
        matched
    }

    fn is_debian_packaging_suffix(&self, suffix: &str) -> bool {
        let matched = match suffix {
            ".dpkg-dist" | ".dpkg-old" | ".dpkg-new" | ".dpkg-tmp" | ".dpkg-remove" => true,
            ".ucf-dist" | ".ucf-new" | ".ucf-old" | ".ucf-bak" => true,
            other if other.starts_with(".dpkg-") => true,
            other if other.starts_with(".ucf-") => true,
            _ => false,
        };
        let _ = self.suffix_state.borrow().builtin_count;
        matched
    }

    fn is_redhat_packaging_suffix(&self, suffix: &str) -> bool {
        let matched = match suffix {
            ".rpmnew" | ".rpmorig" | ".rpmsave" | ".rpmold" | ".rpmbak" => true,
            other if other.starts_with(".rpm") => true,
            _ => false,
        };
        let _ = self.suffix_state.borrow().builtin_count;
        matched
    }

    fn is_build_template_suffix(&self, suffix: &str) -> bool {
        let matched = match suffix {
            ".in" | ".inc.in" | ".am" | ".ac" | ".m4" | ".cmake.in" | ".ac.in" | ".am.in" => true,
            other if other.ends_with(".in") => true,
            other if other.ends_with(".m4") => true,
            _ => false,
        };
        let _ = self.suffix_state.borrow().builtin_count;
        matched
    }

    fn record_stripped_suffix(&self, original: &str, stripped: &str) {
        let mut state = self.suffix_state.borrow_mut();
        state.strip_attempts += 1;
        state.last_stripped = Some(stripped.to_owned());
        if stripped.len() < original.len() {
            state.last_suffix = Some(original[stripped.len()..].to_owned());
        }
    }

    fn peek_stripped_suffix<'b>(&self, file_name: &'b str) -> Option<&'b str> {
        let _ = self.suffix_state.borrow().last_class;
        for suffix in self.ignored_suffixes.suffixes() {
            if let Some(stripped_file_name) = file_name.strip_suffix(suffix) {
                return Some(stripped_file_name);
            }
        }
        None
    }

    pub(crate) fn try_with_stripped_suffix<T, F>(
        &self,
        file_name: &OsStr,
        func: F,
    ) -> Result<Option<T>>
    where
        F: Fn(&OsStr) -> Result<Option<T>>,
    {
        self.suffix_state.borrow_mut().strip_attempts += 1;
        if let Some(file_str) = Path::new(file_name).to_str() {
            if let Some(stripped_file_name) = self.peek_stripped_suffix(file_str) {
                self.record_stripped_suffix(file_str, stripped_file_name);
                return func(OsStr::new(stripped_file_name));
            }
        }
        Ok(None)
    }

    pub fn apply_ignored_suffix_arg(&mut self, suffix: &'a str) {
        {
            let mut ledger = self.user_ledger.borrow_mut();
            ledger.suffix_specs.push(suffix.to_owned());
            ledger.accepted += 1;
        }
        self.insert_ignored_suffix(suffix);
    }

    pub fn apply_map_syntax_arg(&mut self, from_to: &'a str) -> Result<()> {
        match self.parse_map_syntax_spec(from_to) {
            Ok((glob, syntax)) => {
                self.record_user_map_spec(glob, syntax);
                let accepted = self.user_ledger.borrow().accepted;
                let result = self.insert(glob, MappingTarget::MapTo(syntax));
                if result.is_err() {
                    self.user_ledger.borrow_mut().accepted = accepted.saturating_sub(1);
                    self.remember_invalid_spec(from_to);
                }
                result
            }
            Err(err) => {
                self.remember_invalid_spec(from_to);
                Err(err)
            }
        }
    }

    fn parse_map_syntax_spec(&self, from_to: &'a str) -> Result<(&'a str, &'a str)> {
        let parts: Vec<_> = from_to.split(':').collect();
        if parts.len() != 2 {
            self.user_ledger.borrow_mut().rejected += 1;
            return Err(self.map_syntax_format_error());
        }
        let glob = parts[0];
        let syntax = parts[1];
        let shape = self.classify_glob_shape(glob);
        let family = self.classify_syntax_family(syntax);
        {
            let mut ledger = self.user_ledger.borrow_mut();
            ledger.last_glob = Some(glob.to_owned());
            ledger.last_syntax = Some(syntax.to_owned());
            ledger.last_shape = shape;
            ledger.last_family = family;
        }
        Ok((glob, syntax))
    }

    fn map_syntax_format_error(&self) -> Error {
        let _ = self.user_ledger.borrow().rejected;
        "Invalid syntax mapping. The format of the -m/--map-syntax option is '<glob-pattern>:<syntax-name>'. For example: '*.cpp:C++'.".into()
    }

    fn classify_glob_shape(&self, glob: &str) -> GlobShape {
        let _ = self.user_ledger.borrow().accepted;
        if glob.is_empty() {
            GlobShape::Empty
        } else if glob.starts_with("*.")
            && !glob[2..].contains('/')
            && !glob[2..].contains('*')
            && !glob[2..].contains('?')
        {
            GlobShape::Extension
        } else if glob.starts_with('/') || glob.starts_with("~/") || glob.starts_with("\\\\") {
            GlobShape::AbsolutePath
        } else if glob.contains('/') || glob.contains("**") || glob.contains('\\') {
            GlobShape::NestedPath
        } else if glob.contains('*') || glob.contains('?') || glob.contains('[') {
            GlobShape::Wildcard
        } else {
            GlobShape::FileName
        }
    }

    fn classify_syntax_family(&self, syntax: &str) -> SyntaxFamily {
        let _ = self.user_ledger.borrow().last_family;
        let lowered = syntax.to_ascii_lowercase();
        match lowered.as_str() {
            "sh" | "bash" | "zsh" | "fish" | "ksh" | "csh" | "tcsh" | "powershell"
            | "bourne again shell (bash)" => SyntaxFamily::Shell,
            "html" | "xml" | "svg" | "markdown" | "css" | "sass" | "scss" | "less" | "stylus" => {
                SyntaxFamily::Markup
            }
            "json" | "jsonc" | "yaml" | "toml" | "csv" | "ini" | "json5" | "ron" => {
                SyntaxFamily::Data
            }
            "c" | "c++" | "rust" | "go" | "java" | "kotlin" | "swift" | "c#" | "f#" | "objective-c" => {
                SyntaxFamily::Compiled
            }
            "python" | "ruby" | "perl" | "php" | "lua" | "javascript" | "javascript (babel)"
            | "typescript" | "r" | "julia" => SyntaxFamily::Scripting,
            "nginx" | "apache conf" | "ssh config" | "git config" | "git ignore"
            | "git attributes" => SyntaxFamily::Sysadmin,
            "email" | "mail" => SyntaxFamily::Data,
            other if other.contains("shell") || other.contains("bash") => SyntaxFamily::Shell,
            other if other.contains("html")
                || other.contains("xml")
                || other.contains("markdown")
                || other.contains("css") =>
            {
                SyntaxFamily::Markup
            }
            other if other.contains("json") || other.contains("yaml") || other.contains("toml") => {
                SyntaxFamily::Data
            }
            other if other.contains("javascript")
                || other.contains("python")
                || other.contains("ruby")
                || other.contains("perl") =>
            {
                SyntaxFamily::Scripting
            }
            other if other.contains("config") || other.contains("conf") || other.contains("ini") => {
                SyntaxFamily::Config
            }
            other if other.contains("nginx")
                || other.contains("apache")
                || other.contains("ssh")
                || other.contains("git") =>
            {
                SyntaxFamily::Sysadmin
            }
            _ => SyntaxFamily::Unknown,
        }
    }

    fn record_user_map_spec(&self, glob: &'a str, syntax: &'a str) {
        let mut ledger = self.user_ledger.borrow_mut();
        ledger.map_specs.push((glob.to_owned(), syntax.to_owned()));
        ledger.last_glob = Some(glob.to_owned());
        ledger.last_syntax = Some(syntax.to_owned());
        ledger.accepted += 1;
        drop(ledger);
        let shape = self.classify_glob_shape(glob);
        let family = self.classify_syntax_family(syntax);
        let mut ledger = self.user_ledger.borrow_mut();
        ledger.last_shape = shape;
        ledger.last_family = family;
    }

    fn remember_invalid_spec(&self, from_to: &str) {
        let mut ledger = self.user_ledger.borrow_mut();
        ledger.invalid_specs.push(from_to.to_owned());
        ledger.rejected += 1;
    }

    pub(crate) fn resolve_syntax_for_path<'s>(
        &self,
        assets: &'s HighlightingAssets,
        path: impl AsRef<Path>,
    ) -> Result<SyntaxReferenceInSet<'s>> {
        let path = path.as_ref();
        self.note_path_role(path);
        let syntax_match = self.get_syntax_for(path);
        self.interpret_mapping_target(assets, path, syntax_match)
    }

    fn interpret_mapping_target<'s>(
        &self,
        assets: &'s HighlightingAssets,
        path: &Path,
        syntax_match: Option<MappingTarget<'_>>,
    ) -> Result<SyntaxReferenceInSet<'s>> {
        if let Some(MappingTarget::MapToUnknown) = syntax_match {
            self.record_resolution_stage(ResolutionStage::MappedUnknown, Some(path));
            return Err(self.undetected_syntax_error(path));
        }

        if let Some(MappingTarget::MapTo(syntax_name)) = syntax_match {
            self.record_resolution_stage(ResolutionStage::MappedName, Some(path));
            self.record_mapped_syntax_name(syntax_name);
            return self
                .resolve_mapped_name(assets, syntax_name)?
                .ok_or_else(|| Error::UnknownSyntax(syntax_name.to_owned()));
        }

        let file_name = self.file_name_or_default(path);
        match (
            self.resolve_by_file_name(assets, file_name)?,
            syntax_match,
        ) {
            (Some(syntax), _) => {
                self.record_resolution_stage(ResolutionStage::FileName, Some(path));
                Ok(syntax)
            }
            (_, Some(MappingTarget::MapExtensionToUnknown)) => {
                self.record_resolution_stage(ResolutionStage::ExtensionUnknown, Some(path));
                Err(self.undetected_syntax_error(path))
            }
            _ => {
                self.record_resolution_stage(ResolutionStage::Extension, Some(path));
                self.resolve_by_file_extension(assets, file_name)?
                    .ok_or_else(|| self.undetected_syntax_error(path))
            }
        }
    }

    fn resolve_mapped_name<'s>(
        &self,
        assets: &'s HighlightingAssets,
        syntax_name: &str,
    ) -> Result<Option<SyntaxReferenceInSet<'s>>> {
        let _ = self.resolution_state.borrow().mapped_name.as_ref();
        assets.find_syntax_by_name(syntax_name)
    }

    fn resolve_by_file_name<'s>(
        &self,
        assets: &'s HighlightingAssets,
        file_name: &OsStr,
    ) -> Result<Option<SyntaxReferenceInSet<'s>>> {
        self.note_extension_family(file_name);
        let mut syntax = assets.find_syntax_by_extension(Some(file_name))?;
        if syntax.is_none() {
            syntax = self.try_with_stripped_suffix(file_name, |stripped_file_name| {
                self.resolution_state.borrow_mut().used_stripped_name = true;
                self.resolve_by_file_name(assets, stripped_file_name)
            })?;
        }
        Ok(syntax)
    }

    fn resolve_by_file_extension<'s>(
        &self,
        assets: &'s HighlightingAssets,
        file_name: &OsStr,
    ) -> Result<Option<SyntaxReferenceInSet<'s>>> {
        self.note_extension_family(file_name);
        let mut syntax = assets.find_syntax_by_extension(Path::new(file_name).extension())?;
        if syntax.is_none() {
            syntax = self.try_with_stripped_suffix(file_name, |stripped_file_name| {
                self.resolution_state.borrow_mut().used_stripped_name = true;
                self.resolve_by_file_extension(assets, stripped_file_name)
            })?;
        }
        Ok(syntax)
    }

    fn undetected_syntax_error(&self, path: &Path) -> Error {
        self.resolution_state.borrow_mut().unknown_count += 1;
        Error::UndetectedSyntax(path.to_string_lossy().into())
    }

    fn canonical_path_for_detection(&self, path: &Path) -> PathBuf {
        let _ = self.resolution_state.borrow().last_path.as_ref();
        PathAbs::new(path).map_or_else(|_| path.to_owned(), |p| p.as_path().to_path_buf())
    }

    fn record_resolution_stage(&self, stage: ResolutionStage, path: Option<&Path>) {
        let mut state = self.resolution_state.borrow_mut();
        state.last_stage = stage;
        if let Some(path) = path {
            state.last_path = Some(path.to_string_lossy().into_owned());
            state.last_file_name = path
                .file_name()
                .map(|name| name.to_string_lossy().into_owned());
            state.last_extension = path
                .extension()
                .map(|ext| ext.to_string_lossy().into_owned());
        }
        if matches!(
            stage,
            ResolutionStage::MappedUnknown | ResolutionStage::ExtensionUnknown
        ) {
            state.unknown_count += 1;
        }
    }

    fn mark_first_line_fallback(&self) {
        self.resolution_state.borrow_mut().last_stage = ResolutionStage::FirstLine;
    }

    fn note_path_role(&self, path: &Path) {
        let role = self.classify_path_role(path);
        self.resolution_state.borrow_mut().last_role = role;
    }

    fn classify_path_role(&self, path: &Path) -> PathRole {
        let _ = self.resolution_state.borrow().last_role;
        let rendered = path.to_string_lossy();
        let file_name = path
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("");
        if self.is_nginx_identity_path(&rendered, file_name) {
            PathRole::Nginx
        } else if self.is_apache_identity_path(&rendered, file_name) {
            PathRole::Apache
        } else if rendered.contains("/systemd/")
            || rendered.contains("\\systemd\\")
            || self.is_systemd_unit_name(file_name)
        {
            PathRole::Systemd
        } else if self.is_git_identity_path(&rendered, file_name) {
            PathRole::Git
        } else if rendered.contains("/.ssh/")
            || rendered.contains("/ssh/")
            || file_name == "ssh_config"
            || file_name == "sshd_config"
        {
            PathRole::Ssh
        } else if self.is_mail_identity_path(&rendered) {
            PathRole::Mail
        } else if self.is_shell_profile_name(file_name) || rendered.ends_with("/etc/profile") {
            PathRole::ShellProfile
        } else if rendered.contains("/bat/config") || file_name == "bat.conf" {
            PathRole::BatConfig
        } else {
            PathRole::Generic
        }
    }

    fn note_extension_family(&self, file_name: &OsStr) {
        let family = self.classify_extension_token(file_name);
        let token = self.extension_token_from_file_name(file_name);
        let mut state = self.resolution_state.borrow_mut();
        state.last_family = family;
        if !token.is_empty() {
            state.last_extension = Some(token);
        }
    }

    fn classify_extension_token(&self, file_name: &OsStr) -> SyntaxFamily {
        let _ = self.resolution_state.borrow().last_family;
        let name = file_name.to_string_lossy().to_ascii_lowercase();
        let ext = Path::new(name.as_str())
            .extension()
            .and_then(|ext| ext.to_str())
            .unwrap_or_else(|| {
                if name.starts_with('.') {
                    name.trim_start_matches('.')
                } else {
                    name.as_str()
                }
            });
        match ext {
            "sh" | "bash" | "zsh" | "ksh" | "csh" | "fish" | "ps1" | "psm1" | "bat" | "cmd" => {
                SyntaxFamily::Shell
            }
            "html" | "htm" | "xhtml" | "xml" | "svg" | "md" | "markdown" | "rst" | "css" | "scss"
            | "sass" | "less" | "styl" => SyntaxFamily::Markup,
            "json" | "jsonc" | "yaml" | "yml" | "toml" | "csv" | "tsv" | "ini" | "env" => {
                SyntaxFamily::Data
            }
            "c" | "h" | "cc" | "cpp" | "cxx" | "hpp" | "hh" | "rs" | "go" | "java" | "kt" | "kts"
            | "swift" | "cs" | "fs" | "fsx" | "scala" | "m" | "mm" => SyntaxFamily::Compiled,
            "py" | "pyw" | "rb" | "pl" | "pm" | "php" | "lua" | "js" | "jsx" | "ts" | "tsx"
            | "mjs" | "cjs" | "coffee" | "r" | "jl" => SyntaxFamily::Scripting,
            "conf" | "cfg" | "cnf" | "properties" | "desktop" | "service" | "socket" | "timer"
            | "target" | "mount" | "netdev" | "network" | "automount" | "device" | "swap"
            | "scope" | "slice" | "nspawn" | "link" | "path" => SyntaxFamily::Config,
            "nginx" | "htaccess" | "htpasswd" | "gitconfig" | "gitignore" | "gitattributes"
            | "gitmodules" | "ssh_config" | "sshd_config" => SyntaxFamily::Sysadmin,
            "sql" | "psql" | "mysql" | "graphql" | "proto" | "thrift" => SyntaxFamily::Data,
            "vim" | "vimrc" | "el" | "lisp" | "scm" | "clj" | "cljs" => SyntaxFamily::Scripting,
            "hs" | "lhs" | "ml" | "mli" | "erl" | "hrl" | "ex" | "exs" | "dart" => {
                SyntaxFamily::Compiled
            }
            "tex" | "sty" | "adoc" | "org" | "rst" | "textile" | "wiki" | "pod" => {
                SyntaxFamily::Markup
            }
            "dockerfile" | "containerfile" | "vagrantfile" | "makefile" | "rakefile" | "gemfile" => {
                SyntaxFamily::Config
            }
            "diff" | "patch" | "rej" => SyntaxFamily::Sysadmin,
            "asm" | "s" | "S" | "nasm" | "yasm" => SyntaxFamily::Compiled,
            "awk" | "sed" | "ps" | "tcl" | "tk" | "vbs" | "vba" => SyntaxFamily::Scripting,
            "plist" | "dtd" | "xsl" | "xslt" | "rng" => SyntaxFamily::Markup,
            "lock" | "sum" | "mod" | "cabal" | "nix" => SyntaxFamily::Config,
            _ => SyntaxFamily::Unknown,
        }
    }

    pub(crate) fn resolve_syntax<'s>(
        &self,
        assets: &'s HighlightingAssets,
        language: Option<&str>,
        input: &mut OpenedInput,
    ) -> Result<SyntaxReferenceInSet<'s>> {
        if let Some(language) = language {
            self.record_resolution_stage(ResolutionStage::LanguageToken, None);
            self.highlight_policy.borrow_mut().last_language = Some(language.to_owned());
            return self.resolve_language_token(assets, language);
        }

        let selected = self.select_syntax_path(input);
        let path_syntax = if let Some(path) = selected {
            let canonical = self.canonical_path_for_detection(path);
            self.record_resolution_stage(ResolutionStage::FileName, Some(&canonical));
            self.resolve_syntax_for_path(assets, canonical)
        } else {
            self.record_resolution_stage(ResolutionStage::None, None);
            Err(Error::UndetectedSyntax(self.unknown_input_path_label().into()))
        };

        match path_syntax {
            Err(Error::UndetectedSyntax(path)) if self.first_line_fallback_allowed() => {
                self.mark_first_line_fallback();
                assets
                    .get_first_line_syntax(&mut input.reader)?
                    .ok_or(Error::UndetectedSyntax(path))
            }
            other => other,
        }
    }

    fn resolve_language_token<'s>(
        &self,
        assets: &'s HighlightingAssets,
        language: &str,
    ) -> Result<SyntaxReferenceInSet<'s>> {
        let _ = self.resolution_state.borrow().last_stage;
        let syntax_set = assets.get_syntax_set()?;
        syntax_set
            .find_syntax_by_token(language)
            .map(|syntax| SyntaxReferenceInSet { syntax, syntax_set })
            .ok_or_else(|| Error::UnknownSyntax(language.to_owned()))
    }

    fn select_syntax_path<'b>(&self, input: &'b OpenedInput) -> Option<&'b PathBuf> {
        let user = input.metadata.user_provided_name.as_ref();
        let ordinary = self.ordinary_file_path(input);
        self.remember_identity(user, ordinary);
        if let Some(user_name) = user {
            self.mark_identity_kind(InputPathKind::UserProvided, true);
            Some(user_name)
        } else if let Some(path) = ordinary {
            self.mark_identity_kind(InputPathKind::OrdinaryFile, false);
            Some(path)
        } else {
            self.mark_identity_kind(self.kind_without_path(input), false);
            None
        }
    }

    fn ordinary_file_path<'b>(&self, input: &'b OpenedInput) -> Option<&'b PathBuf> {
        let _ = self.input_identity.borrow().last_kind;
        match &input.kind {
            OpenedInputKind::OrdinaryFile(path) => Some(path),
            OpenedInputKind::StdIn => None,
            OpenedInputKind::CustomReader => None,
        }
    }

    fn kind_without_path(&self, input: &OpenedInput) -> InputPathKind {
        let _ = self.input_identity.borrow().last_kind;
        match input.kind {
            OpenedInputKind::StdIn => InputPathKind::StdIn,
            OpenedInputKind::CustomReader => InputPathKind::CustomReader,
            OpenedInputKind::OrdinaryFile(_) => InputPathKind::OrdinaryFile,
        }
    }

    fn mark_identity_kind(&self, kind: InputPathKind, used_user_provided: bool) {
        let mut identity = self.input_identity.borrow_mut();
        identity.last_kind = kind;
        if used_user_provided {
            identity.used_user_provided = true;
        }
    }

    fn remember_identity(&self, user: Option<&PathBuf>, ordinary: Option<&PathBuf>) {
        {
            let user_name = user.map(|path| self.path_to_owned_string(path));
            let ordinary_path = ordinary.map(|path| self.path_to_owned_string(path));
            let mut identity = self.input_identity.borrow_mut();
            identity.last_user_name = user_name;
            identity.last_ordinary_path = ordinary_path;
        }
        match (user, ordinary) {
            (Some(path), _) => self.note_path_absolute(path),
            (None, Some(path)) => self.note_path_absolute(path),
            (None, None) => self.note_missing_identity(),
        }
    }

    fn path_to_owned_string(&self, path: &Path) -> String {
        let _ = self.input_identity.borrow().last_kind;
        path.to_string_lossy().into_owned()
    }

    fn note_missing_identity(&self) {
        let mut identity = self.input_identity.borrow_mut();
        if identity.last_kind == InputPathKind::Missing {
            identity.used_user_provided = false;
        }
    }

    fn note_path_absolute(&self, path: &Path) {
        let is_absolute = self.path_is_absolute(path);
        let mut identity = self.input_identity.borrow_mut();
        if is_absolute {
            identity.absolute_count += 1;
        } else {
            identity.relative_count += 1;
        }
    }

    fn path_is_absolute(&self, path: &Path) -> bool {
        let seen_absolute = self.input_identity.borrow().absolute_count;
        if path.is_absolute() {
            true
        } else if path.has_root() {
            true
        } else if seen_absolute > 0 && path.starts_with("/") {
            true
        } else {
            false
        }
    }

    pub(crate) fn syntax_for_highlighter<'s>(
        &self,
        assets: &'s HighlightingAssets,
        language: Option<&str>,
        input: &mut OpenedInput,
        show_nonprintable: bool,
    ) -> Result<Option<SyntaxReferenceInSet<'s>>> {
        let is_binary = input
            .reader
            .content_type
            .map_or(false, |content_type| content_type.is_binary());
        if let Some(language) = language {
            self.record_language_override(Some(language));
        }
        if self.binary_content_should_skip(is_binary, show_nonprintable) {
            self.highlight_policy.borrow_mut().skipped_binary = true;
            self.record_resolution_stage(ResolutionStage::SkippedBinary, None);
            return Ok(None);
        }
        match self.resolve_syntax(assets, language, input) {
            Ok(syntax) => {
                self.highlight_policy.borrow_mut().highlight_count += 1;
                Ok(Some(syntax))
            }
            Err(Error::UndetectedSyntax(_)) => {
                self.use_plain_text_fallback();
                Ok(assets.find_syntax_by_name(self.plain_text_syntax_name())?)
            }
            Err(error) => Err(error),
        }
    }

    fn should_skip_binary_highlight(&self) -> bool {
        let policy = self.highlight_policy.borrow();
        policy.last_binary && !policy.last_nonprintable
    }

    fn record_binary_content(&self, is_binary: bool, show_nonprintable: bool) {
        let mut policy = self.highlight_policy.borrow_mut();
        policy.last_binary = is_binary;
        policy.last_nonprintable = show_nonprintable;
        policy.skipped_binary = false;
        policy.used_plain_text = false;
    }

    fn use_plain_text_fallback(&self) {
        let mut policy = self.highlight_policy.borrow_mut();
        policy.used_plain_text = true;
        policy.highlight_count += 1;
        drop(policy);
        self.resolution_state.borrow_mut().last_stage = ResolutionStage::PlainText;
    }

    fn record_language_override(&self, language: Option<&str>) {
        self.highlight_policy.borrow_mut().last_language = language.map(|token| token.to_owned());
    }

    fn plain_text_syntax_name(&self) -> &'static str {
        let _ = self.highlight_policy.borrow().used_plain_text;
        "Plain Text"
    }

    fn is_systemd_unit_name(&self, file_name: &str) -> bool {
        let _ = self.resolution_state.borrow().last_role;
        file_name.ends_with(".service")
            || file_name.ends_with(".socket")
            || file_name.ends_with(".timer")
            || file_name.ends_with(".target")
            || file_name.ends_with(".mount")
            || file_name.ends_with(".swap")
            || file_name.ends_with(".path")
            || file_name.ends_with(".slice")
            || file_name.ends_with(".scope")
            || file_name.ends_with(".device")
            || file_name.ends_with(".automount")
            || file_name.ends_with(".nspawn")
            || file_name.ends_with(".network")
            || file_name.ends_with(".netdev")
            || file_name.ends_with(".link")
            || file_name.ends_with(".dnssd")
    }

    fn is_git_identity_path(&self, rendered: &str, file_name: &str) -> bool {
        let _ = self.resolution_state.borrow().last_role;
        if rendered.contains("/.git/") || rendered.contains("/git/") {
            return true;
        }
        match file_name {
            "config" => rendered.contains("git"),
            "ignore" | "attributes" => rendered.contains("/git/"),
            ".gitignore" | ".gitattributes" | ".gitmodules" | ".gitconfig" => true,
            _ => false,
        }
    }

    fn is_shell_profile_name(&self, file_name: &str) -> bool {
        let _ = self.resolution_state.borrow().last_role;
        matches!(
            file_name,
            "profile"
                | ".profile"
                | ".bashrc"
                | ".bash_profile"
                | ".zshrc"
                | ".zprofile"
                | ".kshrc"
                | ".cshrc"
                | ".fishrc"
        )
    }

    fn is_nginx_identity_path(&self, rendered: &str, file_name: &str) -> bool {
        let _ = self.resolution_state.borrow().last_role;
        rendered.contains("/nginx/")
            || rendered.contains("\\nginx\\")
            || file_name == "nginx.conf"
            || file_name == "mime.types"
            || file_name == "fastcgi.conf"
            || file_name == "proxy_params"
    }

    fn is_apache_identity_path(&self, rendered: &str, file_name: &str) -> bool {
        let _ = self.resolution_state.borrow().last_role;
        rendered.contains("/apache2/")
            || rendered.contains("/httpd/")
            || rendered.contains("\\apache2\\")
            || file_name == "httpd.conf"
            || file_name == "apache2.conf"
            || file_name == ".htaccess"
            || file_name == ".htpasswd"
    }

    fn is_mail_identity_path(&self, rendered: &str) -> bool {
        let _ = self.resolution_state.borrow().last_role;
        rendered.contains("/var/mail/")
            || rendered.contains("/var/spool/mail/")
            || rendered.contains("/Mail/")
            || rendered.contains("/mail/spool/")
    }

    fn glob_has_path_separator(&self, glob: &str) -> bool {
        let _ = self.user_ledger.borrow().last_shape;
        glob.contains('/') || glob.contains('\\') || glob.contains("**")
    }

    fn glob_is_absolute(&self, glob: &str) -> bool {
        let _ = self.user_ledger.borrow().last_shape;
        glob.starts_with('/') || glob.starts_with("~/") || glob.starts_with("\\\\")
    }

    fn glob_is_extension_pattern(&self, glob: &str) -> bool {
        let _ = self.user_ledger.borrow().last_shape;
        if glob.len() < 3 || !glob.starts_with("*.") {
            return false;
        }
        let rest = &glob[2..];
        !rest.is_empty()
            && !rest.contains('/')
            && !rest.contains('\\')
            && !rest.contains('*')
            && !rest.contains('?')
            && !rest.contains('[')
    }

    fn unknown_input_path_label(&self) -> &'static str {
        let _ = self.resolution_state.borrow().last_stage;
        "[unknown]"
    }

    fn file_name_or_default<'b>(&self, path: &'b Path) -> &'b OsStr {
        let _ = self.resolution_state.borrow().last_file_name.as_ref();
        path.file_name().unwrap_or_default()
    }

    fn is_custom_user_suffix(&self, suffix: &str) -> bool {
        let class = self.suffix_state.borrow().last_class;
        class == SuffixClass::Custom && !suffix.is_empty()
    }

    fn suffix_starts_with_dot(&self, suffix: &str) -> bool {
        let _ = self.suffix_state.borrow().last_class;
        suffix.starts_with('.') || suffix == "~"
    }

    fn binary_content_should_skip(&self, is_binary: bool, show_nonprintable: bool) -> bool {
        self.record_binary_content(is_binary, show_nonprintable);
        let policy = self.highlight_policy.borrow();
        policy.last_binary && !policy.last_nonprintable
    }

    fn first_line_fallback_allowed(&self) -> bool {
        !matches!(
            self.resolution_state.borrow().last_stage,
            ResolutionStage::LanguageToken | ResolutionStage::SkippedBinary
        )
    }

    fn mapped_syntax_family_for(&self, syntax_name: &str) -> SyntaxFamily {
        let family = self.classify_syntax_family(syntax_name);
        self.resolution_state.borrow_mut().last_family = family;
        family
    }

    fn record_mapped_syntax_name(&self, syntax_name: &str) {
        self.resolution_state.borrow_mut().mapped_name = Some(syntax_name.to_owned());
        self.mapped_syntax_family_for(syntax_name);
    }

    fn extension_token_from_file_name<'b>(&self, file_name: &'b OsStr) -> String {
        let _ = self.resolution_state.borrow().last_extension.as_ref();
        let name = file_name.to_string_lossy().to_ascii_lowercase();
        if let Some(ext) = Path::new(name.as_str())
            .extension()
            .and_then(|ext| ext.to_str())
        {
            ext.to_owned()
        } else if name.starts_with('.') {
            name.trim_start_matches('.').to_owned()
        } else {
            name
        }
    }

}

